import sys

def start_program():
    input_number = int(sys.stdin.read().strip())
    print(compute_answer(input_number))

def compute_answer(n):
    max_len = int(4e5)
    upper_part = [0] * max_len
    lower_part = [0] * max_len
    for i in range(1, max_len):
        lower_part[i] = i
        upper_part[i] = n // i
    prime_flags = [True] * max_len
    prime_flags[0] = False
    prime_flags[1] = False

    primes = []
    for i in range(2, max_len):
        if not prime_flags[i]:
            continue
        primes.append(i)
        for j in range(i * 2, max_len, i):
            prime_flags[j] = False

    for index, p in enumerate(primes):
        for i in range(1, max_len):
            if n // i < p * p:
                break
            val = p * i
            if val < max_len:
                upper_part[i] -= (upper_part[val] - (index + 1))
            else:
                if n // i // p < max_len:
                    lower_part[n // i // p] -= (lower_part[n // i // p] - (index + 1))
        for i in range(max_len - 1, p * p - 1, -1):
            lower_part[i] -= lower_part[i // p] - (index + 1)

    total_primes_count = 0
    for p in primes:
        if p * p > n:
            break
        if p * p * p <= n and p * p * p > 0:
            total_primes_count += 1
        if n // p > p:
            if p < max_len:
                total_primes_count += upper_part[p] - lower_part[p]
            else:
                total_primes_count += lower_part[n // p] - lower_part[p]
    return total_primes_count

if __name__ == "__main__":
    start_program()

